# Load all grids from this session
import os, glob, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR')
    if not session_dir:
        return {}
    session_path = os.path.join(session_dir, '..', 'sessions')
    try:
        basename = os.path.basename(session_path)
        jsonl_path = os.path.join(session_dir, '..', 'sessions', basename + '.jsonl')
    except:
        jsonl_path = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')

    if os.path.exists(jsonl_path):
        with open(jsonl_path) as f:
            lines = f.read()
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', lines):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in lines[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    return {}

os.environ['RLM_SESSION_DIR'] = '/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-8/play/users/u005/system/state/sessions'
G = load_grids()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n{k}: {len(v)}x{len(v[0]) if v else 0}")
    print(v)

